def find_minimal_edit(s_in, s_out):
    """Find the minimal edit between two strings"""
    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))

    # Check for insertion/deletion
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're inserting or deleting
            if len(s_in) < len(s_out):
                # Insertion case - s_out has extra char at position i
                return (s_in[i:], s_out[i:], i)
            elif len(s_in) > len(s_out):
                # Deletion case - s_in has extra char at position i  
                return (s_in[i], s_out[i:], i)
            else:
                # Substitution case
                return (s_in[i], s_out[i], i)

    # If we reach here, one string is prefix of other
    if len(s_in) < len(s_out):
        # Insertion at end
        return (s_in[-1:], s_out[-1:], len(s_in)-1) if len(s_in) > 0 else (s_in, s_out, 0)
    elif len(s_in) > len(s_out):
        # Deletion at end
        return (s_in[-1], s_out[-1], len(s_out)-1) if len(s_out) > 0 else (s_in, s_out, 0)
    else:
        # Strings are identical
        return (s_in, s_out, -1)

